import { defineEventHandler, getQuery, createError } from 'h3';
import { prisma } from '~/server/utils/prisma';
import { z } from 'zod';

const userQuerySchema = z.object({
  page: z.coerce.number().default(1),
  limit: z.coerce.number().default(10),
  search: z.string().optional(),
  role: z.enum(['ADMIN', 'MEMBER', 'GUEST']).optional(),
});

export default defineEventHandler(async (event) => {
  const query = getQuery(event);
  const result = userQuerySchema.safeParse(query);
  if (!result.success) {
    throw createError({ statusCode: 400, statusMessage: 'Invalid Query Parameters', data: result.error.flatten() });
  }
  const { page, limit, search, role } = result.data;
  const where = {
    ...(search ? { OR: [{ name: { contains: search, mode: 'insensitive' } }, { email: { contains: search, mode: 'insensitive' } }] } : {}),
    ...(role ? { role } : {}),
  };
  const [total, users] = await prisma.$transaction([
    prisma.user.count({ where }),
    prisma.user.findMany({ where, skip: (page - 1) * limit, take: limit, select: { id: true, name: true, email: true, role: true, createdAt: true } }),
  ]);
  return { success: true, data: users, pagination: { total, page, limit, totalPages: Math.ceil(total / limit) } };
});

