import { ref, computed } from 'vue';
import type { UserDTO, UserQueryContract, PaginatedResponse } from '~/types/user.contract';

export function useUsers() {
  const users = ref<UserDTO[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0, totalPages: 0 });

  async function fetchUsers(query: UserQueryContract = {}) {
    loading.value = true;
    error.value = null;
    try {
      const res = await $fetch<PaginatedResponse<UserDTO>>('/api/v1/users', { query });
      users.value = res.data;
      pagination.value = res.pagination;
    } catch (err: any) {
      error.value = err.data?.message || err.message || 'Failed to fetch users';
    } finally {
      loading.value = false;
    }
  }

  async function deleteUser(id: string) {
    const previous = [...users.value];
    users.value = users.value.filter(u => u.id !== id);
    try {
      await $fetch(`/api/v1/users/${id}`, { method: 'DELETE' });
    } catch (err: any) {
      users.value = previous;
      error.value = 'Failed to delete user. Changes rolled back.';
    }
  }

  return { users, loading, error, pagination, fetchUsers, deleteUser };
}

