import { defineEventHandler, getHeader, readRawBody, createError } from 'h3';
import crypto from 'node:crypto';
import { prisma } from '~/server/utils/prisma';

const WEBHOOK_SECRET = process.env.STRIPE_WEBHOOK_SECRET || '';

export default defineEventHandler(async (event) => {
  const sig = getHeader(event, 'stripe-signature');
  const rawBody = await readRawBody(event);
  if (!sig || !rawBody) throw createError({ statusCode: 400, statusMessage: 'Missing payload or signature' });

  const hmac = crypto.createHmac('sha256', WEBHOOK_SECRET);
  const expectedSig = hmac.update(rawBody).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
    throw createError({ statusCode: 401, statusMessage: 'Invalid Webhook Signature' });
  }

  const payload = JSON.parse(rawBody.toString());
  return { received: true, eventId: payload.id };
});

